{{ config(materialized='table') }}

with
quarantined as (
    select
        fund_hk,
        fund_business_key,
        fund_name,
        fund_asset_class,
        fund_strategy,
        fund_gp_business_key,
        fund_vintage_year,
        fund_committed_capital_usd,
        fund_status,
        fund_external_identity,
        fund_lei,
        fund_external_id,
        fund_domicile,
        fund_currency,
        load_datetime,
        record_source,
        violation_00
    from {{ ref("investment__fund_external_index__checked_pre") }}
),
violations as (
    select
        'fund_business_key_not_null' as rule_name,
        fund_hk,
        fund_business_key,
        fund_name,
        fund_asset_class,
        fund_strategy,
        fund_gp_business_key,
        fund_vintage_year,
        fund_committed_capital_usd,
        fund_status,
        fund_external_identity,
        fund_lei,
        fund_external_id,
        fund_domicile,
        fund_currency,
        load_datetime,
        record_source
    from quarantined
    where violation_00
)

select
    rule_name,
    fund_hk,
    fund_business_key,
    fund_name,
    fund_asset_class,
    fund_strategy,
    fund_gp_business_key,
    fund_vintage_year,
    fund_committed_capital_usd,
    fund_status,
    fund_external_identity,
    fund_lei,
    fund_external_id,
    fund_domicile,
    fund_currency,
    load_datetime,
    record_source
from violations
